def validate_preapprovals_displayed_for_ma(preapproval_rows, ma_name):
    """
    Validates that all pre-approvals created by the given MA are displayed.
    :param preapproval_rows: List of dicts or objects representing pre-approval rows.
    :param ma_name: Name or ID of the MA.
    :raises AssertionError: If no pre-approvals are found for the MA.
    """
    if not isinstance(preapproval_rows, list):
        raise ValueError("preapproval_rows must be a list")
    count = 0
    for row in preapproval_rows:
        # Assume row is a dict or object with 'ma_name' or similar field
        if isinstance(row, dict):
            if row.get('ma_name') == ma_name:
                count += 1
        else:
            if getattr(row, 'ma_name', None) == ma_name:
                count += 1
    if count == 0:
        raise AssertionError(f"No pre-approvals found for MA: {ma_name}")


